parts.openscad_module:
$fn = 96;

fan_size          = 80;
fan_bolt_circle   = 71;
fan_hole_d        = 4.5;
plate_size        = 92;
plate_thickness   = 4;
air_opening_d     = fan_size - 4;

module fan_mount_80mm() {
  difference() {
    cube([plate_size, plate_size, plate_thickness], center = true);
    cylinder(h = plate_thickness + 2, d = air_opening_d, center = true, $fn = 96);
    for (x = [-fan_bolt_circle/2, fan_bolt_circle/2])
      for (y = [-fan_bolt_circle/2, fan_bolt_circle/2])
        translate([x, y, 0])
          cylinder(h = plate_thickness + 2, d = fan_hole_d, center = true, $fn = 32);
  }
}

fan_mount_80mm();
